CREATE TABLE "TB_REBAL" (
    "REBAL_ID" BIGINT GENERATED BY DEFAULT AS IDENTITY,
    "BASE_DT" DATE NOT NULL,
    "CALC_SEQ" INTEGER NOT NULL DEFAULT 1,
    "ACCT_ID" BIGINT NOT NULL,
    "INV_DEC_ID" BIGINT,
    "REBAL_TP" VARCHAR(20) NOT NULL,
    "REBAL_STS" VARCHAR(30) NOT NULL DEFAULT 'DRAFT',
    "TOT_AST_AMT" NUMERIC(20,4) NOT NULL,
    "CASH_AMT" NUMERIC(20,4) NOT NULL,
    "RSV_CASH_AMT" NUMERIC(20,4) NOT NULL,
    "CUR_CASH_WGT" NUMERIC(10,4),
    "TGT_CASH_WGT" NUMERIC(10,4),
    "CASH_GAP_AMT" NUMERIC(20,4),
    "NEW_CASH_AMT" NUMERIC(20,4) NOT NULL DEFAULT 0,
    "BUY_BGT_AMT" NUMERIC(20,4) NOT NULL DEFAULT 0,
    "SELL_TGT_AMT" NUMERIC(20,4) NOT NULL DEFAULT 0,
    "RCMD_BUY_TOT_AMT" NUMERIC(20,4) NOT NULL DEFAULT 0,
    "RCMD_SELL_TOT_AMT" NUMERIC(20,4) NOT NULL DEFAULT 0,
    "EXEC_BUY_TOT_AMT" NUMERIC(20,4) NOT NULL DEFAULT 0,
    "EXEC_SELL_TOT_AMT" NUMERIC(20,4) NOT NULL DEFAULT 0,
    "ITEM_CNT" INTEGER NOT NULL DEFAULT 0,
    "BUY_ITEM_CNT" INTEGER NOT NULL DEFAULT 0,
    "SELL_ITEM_CNT" INTEGER NOT NULL DEFAULT 0,
    "HOLD_ITEM_CNT" INTEGER NOT NULL DEFAULT 0,
    "REBAL_REQ_YN" CHAR(1) NOT NULL DEFAULT 'N',
    "EXEC_YN" CHAR(1) NOT NULL DEFAULT 'N',
    "COMP_YN" CHAR(1) NOT NULL DEFAULT 'N',
    "CONF_RT" NUMERIC(10,4) NOT NULL,
    "KEY_RSN" VARCHAR(2000),
    "EXEC_RSN" VARCHAR(1000),
    "RULE_VER_NO" INTEGER NOT NULL DEFAULT 1,
    "LATEST_YN" CHAR(1) NOT NULL DEFAULT 'Y',
    "CALC_DTTM" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "APRV_DTTM" TIMESTAMPTZ,
    "COMP_DTTM" TIMESTAMPTZ,
    "CRT_DTTM" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "CRT_USR_ID" VARCHAR(50),
    "UPD_DTTM" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "UPD_USR_ID" VARCHAR(50),
    CONSTRAINT "PK_TB_REBAL" PRIMARY KEY ("REBAL_ID"),
    CONSTRAINT "UK_TB_REBAL_01" UNIQUE ("BASE_DT","CALC_SEQ","ACCT_ID","REBAL_TP"),
    CONSTRAINT "FK_TB_REBAL_01" FOREIGN KEY ("ACCT_ID") REFERENCES "TB_ACCT" ("ACCT_ID"),
    CONSTRAINT "FK_TB_REBAL_02" FOREIGN KEY ("INV_DEC_ID") REFERENCES "TB_INV_DEC" ("INV_DEC_ID"),
    CONSTRAINT "CK_TB_REBAL_01" CHECK ("CALC_SEQ" > 0),
    CONSTRAINT "CK_TB_REBAL_02" CHECK ("REBAL_TP" IN ('WEEKLY','MONTHLY','AD_HOC')),
    CONSTRAINT "CK_TB_REBAL_03" CHECK ("REBAL_STS" IN ('DRAFT','CALCULATED','REVIEWED','APPROVED','PARTIALLY_EXECUTED','COMPLETED','CANCELLED')),
    CONSTRAINT "CK_TB_REBAL_04" CHECK ("TOT_AST_AMT" >= 0 AND "CASH_AMT" >= 0 AND "RSV_CASH_AMT" >= 0),
    CONSTRAINT "CK_TB_REBAL_05" CHECK ("CUR_CASH_WGT" IS NULL OR "CUR_CASH_WGT" BETWEEN 0 AND 100),
    CONSTRAINT "CK_TB_REBAL_06" CHECK ("TGT_CASH_WGT" IS NULL OR "TGT_CASH_WGT" BETWEEN 0 AND 100),
    CONSTRAINT "CK_TB_REBAL_07" CHECK ("NEW_CASH_AMT" >= 0 AND "BUY_BGT_AMT" >= 0 AND "SELL_TGT_AMT" >= 0),
    CONSTRAINT "CK_TB_REBAL_08" CHECK ("RCMD_BUY_TOT_AMT" >= 0 AND "RCMD_SELL_TOT_AMT" >= 0),
    CONSTRAINT "CK_TB_REBAL_09" CHECK ("EXEC_BUY_TOT_AMT" >= 0 AND "EXEC_SELL_TOT_AMT" >= 0),
    CONSTRAINT "CK_TB_REBAL_10" CHECK ("ITEM_CNT" >= 0 AND "BUY_ITEM_CNT" >= 0 AND "SELL_ITEM_CNT" >= 0 AND "HOLD_ITEM_CNT" >= 0),
    CONSTRAINT "CK_TB_REBAL_11" CHECK ("REBAL_REQ_YN" IN ('Y','N') AND "EXEC_YN" IN ('Y','N') AND "COMP_YN" IN ('Y','N') AND "LATEST_YN" IN ('Y','N')),
    CONSTRAINT "CK_TB_REBAL_12" CHECK ("CONF_RT" BETWEEN 0 AND 100),
    CONSTRAINT "CK_TB_REBAL_13" CHECK ("RULE_VER_NO" > 0),
    CONSTRAINT "CK_TB_REBAL_14" CHECK ("RCMD_BUY_TOT_AMT" <= "BUY_BGT_AMT")
);

CREATE INDEX "IDX_TB_REBAL_01" ON "TB_REBAL" ("ACCT_ID","BASE_DT" DESC);
CREATE INDEX "IDX_TB_REBAL_02" ON "TB_REBAL" ("REBAL_TP","BASE_DT" DESC);
CREATE INDEX "IDX_TB_REBAL_03" ON "TB_REBAL" ("REBAL_STS","BASE_DT" DESC);
CREATE INDEX "IDX_TB_REBAL_04" ON "TB_REBAL" ("LATEST_YN","BASE_DT" DESC);
CREATE UNIQUE INDEX "UK_TB_REBAL_LATEST" ON "TB_REBAL" ("BASE_DT","ACCT_ID","REBAL_TP") WHERE "LATEST_YN"='Y';

CREATE TABLE "TB_REBAL_ITEM" (
    "REBAL_ITEM_ID" BIGINT GENERATED BY DEFAULT AS IDENTITY,
    "REBAL_ID" BIGINT NOT NULL,
    "ACCT_ID" BIGINT NOT NULL,
    "STK_ID" BIGINT NOT NULL,
    "HOLD_ID" BIGINT,
    "STK_DEC_ID" BIGINT,
    "BASE_DT" DATE NOT NULL,
    "CUR_PRC" NUMERIC(20,6),
    "HOLD_QTY" NUMERIC(20,8) NOT NULL DEFAULT 0,
    "CUR_AMT" NUMERIC(20,4) NOT NULL DEFAULT 0,
    "CUR_WGT" NUMERIC(10,4),
    "TGT_WGT" NUMERIC(10,4),
    "MIN_WGT" NUMERIC(10,4),
    "MAX_WGT" NUMERIC(10,4),
    "TGT_AMT" NUMERIC(20,4),
    "WGT_GAP_AMT" NUMERIC(20,4),
    "WGT_DIFF_RT" NUMERIC(10,4),
    "WGT_STS" VARCHAR(20) NOT NULL,
    "REBAL_ACT" VARCHAR(30) NOT NULL,
    "BUY_NEED_AMT" NUMERIC(20,4) NOT NULL DEFAULT 0,
    "SELL_NEED_AMT" NUMERIC(20,4) NOT NULL DEFAULT 0,
    "RCMD_BUY_AMT" NUMERIC(20,4) NOT NULL DEFAULT 0,
    "RCMD_SELL_AMT" NUMERIC(20,4) NOT NULL DEFAULT 0,
    "RCMD_BUY_QTY" NUMERIC(20,8),
    "RCMD_SELL_QTY" NUMERIC(20,8),
    "CUR_REG_BUY_AMT" NUMERIC(20,4),
    "NEW_REG_BUY_AMT" NUMERIC(20,4),
    "REG_BUY_CHG_AMT" NUMERIC(20,4),
    "PRIO_NO" INTEGER,
    "PRIO_SCR" NUMERIC(10,4),
    "RISK_GRADE" VARCHAR(20),
    "FUND_DMG_YN" CHAR(1) NOT NULL DEFAULT 'N',
    "TAX_CONSIDER_YN" CHAR(1) NOT NULL DEFAULT 'N',
    "TRADE_LIMIT_YN" CHAR(1) NOT NULL DEFAULT 'N',
    "LIMIT_RSN" VARCHAR(1000),
    "EXEC_YN" CHAR(1) NOT NULL DEFAULT 'N',
    "EXEC_TP" VARCHAR(20),
    "EXEC_AMT" NUMERIC(20,4) NOT NULL DEFAULT 0,
    "EXEC_QTY" NUMERIC(20,8),
    "EXEC_PRC" NUMERIC(20,6),
    "EXEC_DTTM" TIMESTAMPTZ,
    "EXEC_RSN" VARCHAR(1000),
    "ITEM_STS" VARCHAR(30) NOT NULL DEFAULT 'READY',
    "DEC_RSN" VARCHAR(2000),
    "CRT_DTTM" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "UPD_DTTM" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "PK_TB_REBAL_ITEM" PRIMARY KEY ("REBAL_ITEM_ID"),
    CONSTRAINT "UK_TB_REBAL_ITEM_01" UNIQUE ("REBAL_ID","STK_ID"),
    CONSTRAINT "FK_TB_REBAL_ITEM_01" FOREIGN KEY ("REBAL_ID") REFERENCES "TB_REBAL" ("REBAL_ID") ON DELETE CASCADE,
    CONSTRAINT "FK_TB_REBAL_ITEM_02" FOREIGN KEY ("ACCT_ID") REFERENCES "TB_ACCT" ("ACCT_ID"),
    CONSTRAINT "FK_TB_REBAL_ITEM_03" FOREIGN KEY ("STK_ID") REFERENCES "TB_STK" ("STK_ID"),
    CONSTRAINT "FK_TB_REBAL_ITEM_04" FOREIGN KEY ("HOLD_ID") REFERENCES "TB_HOLD" ("HOLD_ID"),
    CONSTRAINT "FK_TB_REBAL_ITEM_05" FOREIGN KEY ("STK_DEC_ID") REFERENCES "TB_STK_DEC" ("STK_DEC_ID"),
    CONSTRAINT "CK_TB_REBAL_ITEM_01" CHECK ("HOLD_QTY" >= 0 AND "CUR_AMT" >= 0),
    CONSTRAINT "CK_TB_REBAL_ITEM_02" CHECK ("CUR_WGT" IS NULL OR "CUR_WGT" BETWEEN 0 AND 100),
    CONSTRAINT "CK_TB_REBAL_ITEM_03" CHECK ("TGT_WGT" IS NULL OR "TGT_WGT" BETWEEN 0 AND 100),
    CONSTRAINT "CK_TB_REBAL_ITEM_04" CHECK ("MIN_WGT" IS NULL OR "MIN_WGT" BETWEEN 0 AND 100),
    CONSTRAINT "CK_TB_REBAL_ITEM_05" CHECK ("MAX_WGT" IS NULL OR "MAX_WGT" BETWEEN 0 AND 100),
    CONSTRAINT "CK_TB_REBAL_ITEM_06" CHECK ("MIN_WGT" IS NULL OR "TGT_WGT" IS NULL OR "MIN_WGT" <= "TGT_WGT"),
    CONSTRAINT "CK_TB_REBAL_ITEM_07" CHECK ("MAX_WGT" IS NULL OR "TGT_WGT" IS NULL OR "TGT_WGT" <= "MAX_WGT"),
    CONSTRAINT "CK_TB_REBAL_ITEM_08" CHECK ("WGT_STS" IN ('UNDERWEIGHT','NORMAL','OVERWEIGHT','EXCLUDED')),
    CONSTRAINT "CK_TB_REBAL_ITEM_09" CHECK ("REBAL_ACT" IN ('BUY','SELL','HOLD','PAUSE_REGULAR_BUY','REDUCE_REGULAR_BUY','INCREASE_REGULAR_BUY','RESUME_REGULAR_BUY','EXCLUDE')),
    CONSTRAINT "CK_TB_REBAL_ITEM_10" CHECK ("BUY_NEED_AMT" >= 0 AND "SELL_NEED_AMT" >= 0 AND "RCMD_BUY_AMT" >= 0 AND "RCMD_SELL_AMT" >= 0),
    CONSTRAINT "CK_TB_REBAL_ITEM_11" CHECK (NOT ("RCMD_BUY_AMT" > 0 AND "RCMD_SELL_AMT" > 0)),
    CONSTRAINT "CK_TB_REBAL_ITEM_12" CHECK ("REBAL_ACT" <> 'BUY' OR "RCMD_SELL_AMT" = 0),
    CONSTRAINT "CK_TB_REBAL_ITEM_13" CHECK ("REBAL_ACT" <> 'SELL' OR "RCMD_BUY_AMT" = 0),
    CONSTRAINT "CK_TB_REBAL_ITEM_14" CHECK ("CUR_REG_BUY_AMT" IS NULL OR "CUR_REG_BUY_AMT" >= 0),
    CONSTRAINT "CK_TB_REBAL_ITEM_15" CHECK ("NEW_REG_BUY_AMT" IS NULL OR "NEW_REG_BUY_AMT" >= 0),
    CONSTRAINT "CK_TB_REBAL_ITEM_16" CHECK ("FUND_DMG_YN" IN ('Y','N') AND "TAX_CONSIDER_YN" IN ('Y','N') AND "TRADE_LIMIT_YN" IN ('Y','N') AND "EXEC_YN" IN ('Y','N')),
    CONSTRAINT "CK_TB_REBAL_ITEM_17" CHECK ("EXEC_TP" IS NULL OR "EXEC_TP" IN ('BUY','SELL','HOLD')),
    CONSTRAINT "CK_TB_REBAL_ITEM_18" CHECK ("EXEC_AMT" >= 0),
    CONSTRAINT "CK_TB_REBAL_ITEM_19" CHECK ("EXEC_QTY" IS NULL OR "EXEC_QTY" >= 0),
    CONSTRAINT "CK_TB_REBAL_ITEM_20" CHECK ("EXEC_TP" <> 'SELL' OR "EXEC_QTY" IS NULL OR "EXEC_QTY" <= "HOLD_QTY"),
    CONSTRAINT "CK_TB_REBAL_ITEM_21" CHECK ("TRADE_LIMIT_YN" <> 'Y' OR "EXEC_YN" = 'N'),
    CONSTRAINT "CK_TB_REBAL_ITEM_22" CHECK ("FUND_DMG_YN" <> 'Y' OR "RCMD_BUY_AMT" = 0),
    CONSTRAINT "CK_TB_REBAL_ITEM_23" CHECK ("ITEM_STS" IN ('READY','APPROVED','EXECUTED','PARTIALLY_EXECUTED','SKIPPED','CANCELLED'))
);

CREATE INDEX "IDX_TB_REBAL_ITEM_01" ON "TB_REBAL_ITEM" ("REBAL_ID","PRIO_NO");
CREATE INDEX "IDX_TB_REBAL_ITEM_02" ON "TB_REBAL_ITEM" ("ACCT_ID","BASE_DT" DESC);
CREATE INDEX "IDX_TB_REBAL_ITEM_03" ON "TB_REBAL_ITEM" ("STK_ID","BASE_DT" DESC);
CREATE INDEX "IDX_TB_REBAL_ITEM_04" ON "TB_REBAL_ITEM" ("REBAL_ACT","ITEM_STS");
CREATE INDEX "IDX_TB_REBAL_ITEM_05" ON "TB_REBAL_ITEM" ("WGT_STS","BASE_DT" DESC);

COMMENT ON TABLE "TB_REBAL" IS '계좌별 주간·월간·수시 리밸런싱 계획';
COMMENT ON TABLE "TB_REBAL_ITEM" IS '리밸런싱 계획의 종목별 조정항목';
COMMENT ON COLUMN "TB_REBAL"."CALC_SEQ" IS '같은 기준일·계좌·유형의 계산순번';
COMMENT ON COLUMN "TB_REBAL"."LATEST_YN" IS '최신 계산 여부';
COMMENT ON COLUMN "TB_REBAL_ITEM"."REBAL_ACT" IS '리밸런싱 권장행동';
COMMENT ON COLUMN "TB_REBAL_ITEM"."REG_BUY_CHG_AMT" IS '정기매수 변경액';
